#!/usr/bin/env python3
"""
Analysis Script - Tecan Plate Reader Loading Isotherm Evaluation
Can be called externally with experiment ID as parameter.
"""

import os
import sys
import json
import argparse
import shutil
from pathlib import Path
from typing import List, Dict, Optional, Tuple, Any

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from scipy.optimize import curve_fit
from sklearn.metrics import r2_score

# Device control server configuration for Tecan
import requests

DEVICE_CONTROL_SERVER = os.getenv('DEVICE_CONTROL_SERVER', 'http://localhost:8000')
DEVICE_API_KEY = os.getenv('DEVICE_API_KEY', 'your-secure-api-key-here')


def check_tecan_data_availability(experiment_id: str) -> dict:
    """Check if Tecan data is available for the given experiment ID."""
    url = f"{DEVICE_CONTROL_SERVER}/api/tecan/data/{experiment_id}/list"
    headers = {'X-API-Key': DEVICE_API_KEY}
    try:
        response = requests.get(url, headers=headers, timeout=10)
        if response.status_code == 200:
            data = response.json()
            return {"available": data.get('total_files', 0) > 0,
                    "total_files": data.get('total_files', 0),
                    "files": data.get('files', [])}
        elif response.status_code == 404:
            return {"available": False, "total_files": 0, "files": [], "error": "No data found"}
        else:
            return {"available": False, "total_files": 0, "files": [], "error": f"Server error: {response.status_code}"}
    except Exception as e:
        return {"available": False, "total_files": 0, "files": [], "error": str(e)}


def fetch_tecan_data_file(experiment_id: str, save_to_folder: str, file_index: int = 0) -> str:
    """Fetch a SINGLE Tecan Excel data file from device control server."""
    url = f"{DEVICE_CONTROL_SERVER}/api/tecan/data/{experiment_id}?file_index={file_index}"
    headers = {'X-API-Key': DEVICE_API_KEY}
    try:
        response = requests.get(url, headers=headers, timeout=30)
        response.raise_for_status()
        save_folder = Path(save_to_folder)
        save_folder.mkdir(parents=True, exist_ok=True)
        filename = f"tecan_data_{experiment_id}.xlsx"
        file_path = save_folder / filename
        with open(file_path, 'wb') as f:
            f.write(response.content)
        print(f"Successfully downloaded Tecan data to: {file_path}")
        return str(file_path)
    except requests.exceptions.ConnectionError:
        raise Exception(f"Cannot connect to device control server at {DEVICE_CONTROL_SERVER}")
    except requests.exceptions.Timeout:
        raise Exception("Timeout while fetching Tecan data from device control server")
    except Exception as e:
        raise Exception(f"Failed to fetch Tecan data for experiment {experiment_id}: {str(e)}")


def get_most_recent_folder(directory, n=0):
    """Finds the n-th most recent subfolder in a given directory."""
    folders = [f for f in os.listdir(directory) if os.path.isdir(os.path.join(directory, f))]
    if not folders:
        return None
    sorted_folders = sorted(folders, key=lambda f: os.path.getctime(os.path.join(directory, f)), reverse=True)
    return os.path.join(directory, sorted_folders[n]) if len(sorted_folders) > n else None


def get_most_recent_excel_file(directory, n=0):
    """Finds the most recent Excel file within the 'Export/xlsx/' subfolder."""
    most_recent_folder = get_most_recent_folder(directory, n)
    if not most_recent_folder:
        return None
    excel_export_path = Path(most_recent_folder) / "Export" / "xlsx"
    if not excel_export_path.exists() or not excel_export_path.is_dir():
        return None
    try:
        files_in_folder = os.listdir(excel_export_path)
        excel_files = [f for f in files_in_folder if f.lower().endswith('.xlsx')]
        if not excel_files:
            return None
        excel_files.sort(key=lambda f: os.path.getctime(Path(excel_export_path) / f), reverse=True)
        return str(Path(excel_export_path) / excel_files[0])
    except Exception:
        return None


def parse_semicolon_floats(value: Any, field_name: str) -> List[float]:
    """Parse a semicolon-separated string of numbers into a list of floats.

    Replaces comma decimal separators, strips whitespace and validates conversion.
    """
    if value is None:
        raise ValueError(f"Metadata field '{field_name}' is None")

    if isinstance(value, (int, float)):
        return [float(value)]

    if not isinstance(value, str):
        raise ValueError(f"Metadata field '{field_name}' must be a string or number, got {type(value)}")

    parts = [p.strip() for p in value.split(';') if p.strip() != '']
    if not parts:
        raise ValueError(f"Metadata field '{field_name}' is empty after splitting")

    floats: List[float] = []
    for p in parts:
        p_num = p.replace(',', '.')
        try:
            floats.append(float(p_num))
        except ValueError:
            raise ValueError(f"Cannot convert '{p}' in '{field_name}' to float")
    return floats


def parse_single_float(value: Any, field_name: str) -> float:
    """Parse a single value into float, allowing strings with comma decimal separator."""
    if value is None:
        raise ValueError(f"Metadata field '{field_name}' is None")
    if isinstance(value, (int, float)):
        return float(value)
    if not isinstance(value, str):
        raise ValueError(f"Metadata field '{field_name}' must be a string or number, got {type(value)}")
    s = value.strip().replace(',', '.')
    if s == '':
        raise ValueError(f"Metadata field '{field_name}' is empty")
    try:
        return float(s)
    except ValueError:
        raise ValueError(f"Cannot convert metadata field '{field_name}' value '{value}' to float")


def parse_int(value: Any, field_name: str) -> int:
    """Parse a value into int, allowing numeric strings."""
    if value is None:
        raise ValueError(f"Metadata field '{field_name}' is None")
    if isinstance(value, int):
        return value
    if isinstance(value, float) and value.is_integer():
        return int(value)
    if not isinstance(value, str):
        raise ValueError(f"Metadata field '{field_name}' must be an int or string, got {type(value)}")
    s = value.strip()
    if s == '':
        raise ValueError(f"Metadata field '{field_name}' is empty")
    try:
        return int(s)
    except ValueError:
        raise ValueError(f"Cannot convert metadata field '{field_name}' value '{value}' to int")


def langmuir_isotherm(c, q_max, K):
    """Langmuir isotherm model: q = q_max * K * c / (1 + K * c)."""
    return q_max * K * c / (1.0 + K * c)


def fit_langmuir(c_eq: np.ndarray, q: np.ndarray) -> Tuple[Optional[float], Optional[float], Optional[float]]:
    """Fit Langmuir isotherm to data.

    Returns (q_max, K, r2). On failure returns (None, None, None).
    """
    # Remove NaN
    mask = np.isfinite(c_eq) & np.isfinite(q)
    c_eq = c_eq[mask]
    q = q[mask]

    if c_eq.size < 3:
        print("WARNING: Not enough data points for Langmuir fit (need at least 3)")
        return None, None, None

    try:
        # Initial guesses based on data
        q_max0 = float(np.nanmax(q)) if np.isfinite(np.nanmax(q)) else 1.0
        if q_max0 <= 0:
            q_max0 = 1.0
        K0 = 1.0 / (np.nanmax(c_eq) if np.nanmax(c_eq) > 0 else 1.0)
        p0 = [q_max0, K0]
        bounds = ([0.0, 0.0], [np.inf, np.inf])
        popt, _pcov = curve_fit(langmuir_isotherm, c_eq, q, p0=p0, bounds=bounds, maxfev=10000)
        q_fit = langmuir_isotherm(c_eq, *popt)
        r2 = r2_score(q, q_fit)

        q_max, K = float(popt[0]), float(popt[1])
        if not (np.isfinite(q_max) and np.isfinite(K)):
            print("WARNING: Non-finite Langmuir fit parameters")
            return None, None, None

        # Simple sanity check: fitted q_max should be within reasonable multiple of max observed q
        max_q_obs = float(np.nanmax(q))
        if max_q_obs <= 0:
            print("WARNING: Non-positive observed q, fit may be meaningless")
            return None, None, None
        if q_max < 0 or q_max > 10 * max_q_obs:
            print("WARNING: Fitted q_max is outside reasonable range, rejecting fit")
            return None, None, None

        return q_max, K, float(r2)
    except Exception as e:
        print(f"WARNING: Langmuir fit failed: {e}")
        return None, None, None


def map_wells_to_conditions(
    absorbance_df: pd.DataFrame,
    num_ligand: int,
    num_salt: int,
    replicates: int,
    ligand_concs: List[float],
    salt_concs: List[float],
) -> pd.DataFrame:
    """Map Tecan plate absorbance values to conditions based on layout.

    absorbance_df: DataFrame of shape (8, 12) with rows A-H and columns 1-12 (index 0-7, 0-11).

    Returns long-format DataFrame with columns:
      well_row, well_col, ligand_index, salt_index, replicate_index,
      c0, salt_conc, absorbance
    """
    if absorbance_df.shape[0] < 8 or absorbance_df.shape[1] < 12:
        raise ValueError("Absorbance data must have at least 8 rows and 12 columns for a 96-well plate")

    if len(ligand_concs) != num_ligand:
        raise ValueError(
            f"Number of ligand concentrations ({len(ligand_concs)}) does not match NUM_LIGAND ({num_ligand})"
        )
    if len(salt_concs) != num_salt:
        raise ValueError(
            f"Number of salt concentrations ({len(salt_concs)}) does not match NUM_SALT ({num_salt})"
        )

    total_wells_needed = num_ligand * num_salt * replicates
    if total_wells_needed > 96:
        raise ValueError(
            f"Total required wells ({total_wells_needed}) exceed 96. Check metadata: "
            f"num_ligand={num_ligand}, num_salt={num_salt}, replicates={replicates}"
        )

    # Define mapping as described: rows correspond to ligand concentrations ascending from A to ...
    # For each salt concentration, we have a block of 'replicates' columns.
    # Salt concentrations are ascending row-wise, but replicates are grouped together in columns.
    # Example: num_salt=4, replicates=3 -> columns 1-3: salt 0, 4-6: salt 1, 7-9: salt 2, 10-12: salt 3

    if num_salt * replicates > 12:
        raise ValueError(
            f"Number of salt concentrations times replicates ({num_salt} * {replicates})"
            f" exceeds number of plate columns (12)."
        )

    records: List[Dict[str, Any]] = []
    row_labels = ["A", "B", "C", "D", "E", "F", "G", "H"]

    for salt_idx in range(num_salt):
        salt_conc = salt_concs[salt_idx]
        for rep_idx in range(replicates):
            col_index = salt_idx * replicates + rep_idx  # 0-based column index
            if col_index >= 12:
                continue
            for lig_idx in range(num_ligand):
                row_index = lig_idx  # 0-based row index, A=0
                if row_index >= 8:
                    continue
                well_row = row_labels[row_index]
                well_col_num = col_index + 1  # 1-based column number
                absorbance = absorbance_df.iat[row_index, col_index]
                records.append(
                    {
                        "well_row": well_row,
                        "well_col": well_col_num,
                        "ligand_index": lig_idx,
                        "salt_index": salt_idx,
                        "replicate_index": rep_idx,
                        "c0": ligand_concs[lig_idx],
                        "salt_conc": salt_conc,
                        "absorbance": float(absorbance) if pd.notna(absorbance) else np.nan,
                    }
                )

    df_long = pd.DataFrame.from_records(records)

    expected_groups = num_ligand * num_salt
    actual_groups = df_long.groupby(["ligand_index", "salt_index"]).size().shape[0]
    if actual_groups != expected_groups:
        raise ValueError(
            f"Well-to-condition mapping produced {actual_groups} groups, "
            f"but expected {expected_groups} (num_ligand * num_salt). Check layout and metadata."
        )

    return df_long


def analyze_experiment(experiment_id: Optional[str] = None, data_folder: str = '../data', results_folder: str = '../results') -> Dict[str, Any]:
    """Main analysis function for Tecan loading isotherm data.

    Args:
        experiment_id (str): Experiment ID
        data_folder (str): Path to data folder
        results_folder (str): Path to results folder

    Returns:
        dict: Analysis results with all key metrics
    """
    results_folder_path = Path(results_folder)
    results_folder_path.mkdir(parents=True, exist_ok=True)

    analysis_results: Dict[str, Any] = {
        "experiment_id": experiment_id,
        "status": "failed",
        "message": "",
        "plots": {},
        "data_outputs": {},
        "metadata": {},
        "files_processed": 0,
        "warnings": [],
    }

    # Auto-detect experiment ID if not provided
    if experiment_id is None:
        if len(sys.argv) > 1 and sys.argv[0].endswith('.py'):
            experiment_id = sys.argv[1]
            analysis_results["experiment_id"] = experiment_id
            print(f"INFO: Using experiment ID from command line: {experiment_id}")
        else:
            # Auto-detect from most recent experiment_*.json in data_folder
            data_path = Path(data_folder)
            if not data_path.exists():
                raise FileNotFoundError(f"Data folder does not exist: {data_folder}")
            json_files = sorted(
                data_path.glob('experiment_*.json'),
                key=lambda p: p.stat().st_mtime,
                reverse=True,
            )
            if not json_files:
                raise FileNotFoundError("No experiment_*.json files found for auto-detection")
            latest = json_files[0]
            name = latest.stem  # experiment_XXXX
            if '_' not in name:
                raise ValueError(f"Cannot parse experiment ID from filename: {latest.name}")
            experiment_id = name.split('_', 1)[1]
            analysis_results["experiment_id"] = experiment_id
            print(f"INFO: Auto-detected most recent experiment ID: {experiment_id}")

    if experiment_id is None:
        raise ValueError("Experiment ID could not be determined")

    data_folder_path = Path(data_folder)
    if not data_folder_path.exists():
        raise FileNotFoundError(f"Data folder not found: {data_folder}")

    # Load experiment JSON (prefer root ../experiment_<id>.json if present)
    root_json_path = Path('..') / f'experiment_{experiment_id}.json'
    if root_json_path.exists():
        data_file_path = root_json_path
    else:
        data_file_path = data_folder_path / f'experiment_{experiment_id}.json'

    print(f"INFO: Loading experiment data from: {data_file_path}")
    try:
        with open(data_file_path, 'r') as f:
            experiment_data = json.load(f)
    except FileNotFoundError:
        raise FileNotFoundError(f"Data file not found: {data_file_path}")
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON format in {data_file_path}: {e}")

    # Extract metadata and extra fields
    try:
        meta_root = experiment_data.get('metadata_decoded') or {}
        metadata_extra = meta_root.get('extra_fields') or {}
    except Exception as e:
        raise KeyError(f"Missing or invalid 'metadata_decoded.extra_fields' structure: {e}")

    def get_field(field_key: str, pretty_name: str) -> Any:
        if field_key not in metadata_extra:
            raise KeyError(f"Missing expected metadata field: {pretty_name}")
        return metadata_extra[field_key].get('value')

    # Required metadata fields per user template
    try:
        ligand_conc_str = get_field('Ligand concentrations', 'Ligand concentrations')
        salt_conc_str = get_field('Salt concentrations', 'Salt concentrations')
        num_ligand_val = get_field('Number of ligand concentrations', 'Number of ligand concentrations')
        num_salt_val = get_field('Number of salt concentrations', 'Number of salt concentrations')
        replicates_val = get_field('Replicates', 'Replicates')
        ligand_unit = get_field('Ligand concentration unit', 'Ligand concentration unit')
        salt_unit = get_field('Salt concentration unit', 'Salt concentration unit')
        calib_slope_val = get_field('Calibration Curve Slope', 'Calibration Curve Slope')
        calib_intercept_val = get_field('Calibration Curve Intercept', 'Calibration Curve Intercept')
        resin_mass_val = get_field('Resin Mass', 'Resin Mass')
        total_volume_val = get_field('Total volume', 'Total volume')
    except KeyError as e:
        raise

    # Parse numeric metadata
    ligand_concs = parse_semicolon_floats(ligand_conc_str, 'Ligand concentrations')
    salt_concs = parse_semicolon_floats(salt_conc_str, 'Salt concentrations')
    num_ligand = parse_int(num_ligand_val, 'Number of ligand concentrations')
    num_salt = parse_int(num_salt_val, 'Number of salt concentrations')
    replicates = parse_int(replicates_val, 'Replicates')
    calib_slope = parse_single_float(calib_slope_val, 'Calibration Curve Slope')
    calib_intercept = parse_single_float(calib_intercept_val, 'Calibration Curve Intercept')
    resin_mass = parse_single_float(resin_mass_val, 'Resin Mass')
    total_volume = parse_single_float(total_volume_val, 'Total volume')

    if num_ligand <= 0 or num_salt <= 0 or replicates <= 0:
        raise ValueError(
            f"Number of ligand concentrations, salt concentrations and replicates must be positive: "
            f"num_ligand={num_ligand}, num_salt={num_salt}, replicates={replicates}"
        )

    if len(ligand_concs) != num_ligand:
        raise ValueError(
            f"Length of ligand concentrations list ({len(ligand_concs)}) does not match 'Number of ligand concentrations' ({num_ligand})"
        )
    if len(salt_concs) != num_salt:
        raise ValueError(
            f"Length of salt concentrations list ({len(salt_concs)}) does not match 'Number of salt concentrations' ({num_salt})"
        )

    if calib_slope == 0:
        raise ValueError("Calibration Curve Slope is zero; cannot invert calibration curve")

    analysis_results["metadata"].update(
        {
            "ligand_concentrations": ligand_concs,
            "salt_concentrations": salt_concs,
            "num_ligand_concentrations": num_ligand,
            "num_salt_concentrations": num_salt,
            "replicates": replicates,
            "ligand_concentration_unit": ligand_unit,
            "salt_concentration_unit": salt_unit,
            "calibration_slope": calib_slope,
            "calibration_intercept": calib_intercept,
            "resin_mass_mg": resin_mass,
            "total_volume_uL": total_volume,
        }
    )

    # Fetch Tecan data (single file pattern, endpoint experiment)
    print(f"Fetching Tecan data for experiment {experiment_id} from device control server...")
    try:
        data_info = check_tecan_data_availability(experiment_id)
        if not data_info.get("available", False):
            raise FileNotFoundError(
                f"No Tecan data available for experiment {experiment_id}: "
                f"{data_info.get('error', 'Unknown error')}"
            )

        print(f"Tecan data found on server: {data_info.get('total_files', 0)} file(s)")
        tecan_data_path_str = fetch_tecan_data_file(experiment_id, str(results_folder_path))
        tecan_data_path = Path(tecan_data_path_str)
        analysis_results["data_outputs"]["tecan_raw_excel"] = str(tecan_data_path.resolve())
    except Exception as device_server_error:
        print(f"Device control server access failed: {device_server_error}. Falling back to local file search...")
        tecan_raw_path = "C:/Users/Public/Documents/Tecan/SparkControl/Workspaces"

        if not Path(tecan_raw_path).exists():
            msg = "Tecan data not available - analysis skipped. This is expected for test runs."
            analysis_results["message"] = msg
            analysis_results["status"] = "success"
            analysis_results["note"] = "No Tecan data found on server or local system."
            print(f"INFO: {analysis_results['message']}")
            # Save JSON and return early
            results_json_file = f"analysis_results_{experiment_id}.json"
            results_json_path = results_folder_path / results_json_file
            with open(results_json_path, 'w') as f:
                json.dump(analysis_results, f, indent=4)
            print(f"Saved analysis results JSON to: {results_json_path}")
            return analysis_results

        most_recent_excel_source = get_most_recent_excel_file(tecan_raw_path)
        if not most_recent_excel_source:
            msg = "No recent Tecan Excel file found - analysis skipped."
            analysis_results["message"] = msg
            analysis_results["status"] = "success"
            print(f"INFO: {analysis_results['message']}")
            results_json_file = f"analysis_results_{experiment_id}.json"
            results_json_path = results_folder_path / results_json_file
            with open(results_json_path, 'w') as f:
                json.dump(analysis_results, f, indent=4)
            print(f"Saved analysis results JSON to: {results_json_path}")
            return analysis_results

        tecan_data_path = results_folder_path / f'tecan_data_{experiment_id}.xlsx'
        shutil.copy(most_recent_excel_source, tecan_data_path)
        print(f"Raw data copied from '{most_recent_excel_source}' to '{tecan_data_path}'")
        analysis_results["data_outputs"]["tecan_raw_excel"] = str(tecan_data_path.resolve())

    # Read absorbance data from Excel: absorbance starts at row 34, column B (A1)
    print("INFO: Reading absorbance data from Tecan Excel file...")
    # We will read an 8x12 block corresponding to A1-H12
    num_rows = 8
    num_cols = 12
    try:
        absorbance_df = pd.read_excel(
            tecan_data_path,
            header=None,
            skiprows=33,  # row 34 is index 33 (0-based)
            usecols=list(range(1, 1 + num_cols)),  # columns B-M -> 1-12
            nrows=num_rows,
        )
    except Exception as e:
        raise RuntimeError(f"Failed to read absorbance data from Excel file {tecan_data_path}: {e}")

    analysis_results["files_processed"] = 1

    # Map wells to experimental conditions
    print("INFO: Mapping wells to experimental conditions...")
    mapping_df = map_wells_to_conditions(
        absorbance_df=absorbance_df,
        num_ligand=num_ligand,
        num_salt=num_salt,
        replicates=replicates,
        ligand_concs=ligand_concs,
        salt_concs=salt_concs,
    )

    # Calculate equilibrium concentrations cE from absorbance
    print("INFO: Calculating equilibrium concentrations from absorbance using calibration curve...")
    # cE = (Absorbance - intercept) / slope
    mapping_df["cE"] = (mapping_df["absorbance"] - calib_intercept) / calib_slope

    # Sanity-check calibration: cE between 0 and max c0, and varies with c0 within each column
    max_c0 = max(ligand_concs)
    if (mapping_df["cE"] < 0).any() or (mapping_df["cE"] > max_c0 + 1e-9).any():
        raise ValueError(
            "Calibration sanity check failed: some equilibrium concentrations cE are outside [0, max(c0)]. "
            "Check that the calibration curve has been applied correctly and metadata are consistent."
        )

    # Check variation of cE across ligand levels for each salt/replicate
    group_cols = ["salt_index", "replicate_index"]
    for (s_idx, r_idx), grp in mapping_df.groupby(group_cols):
        std_cE = float(np.nanstd(grp["cE"]))
        if std_cE < 1e-6:
            msg = (
                f"WARNING: Very low variation in cE across ligand concentrations for salt_index={s_idx}, "
                f"replicate_index={r_idx}. This may indicate an issue with calibration (possibly applied backwards)."
            )
            print(msg)
            analysis_results["warnings"].append(msg)

    # Aggregate replicates: mean and std of cE for each combination of ligand and salt
    print("INFO: Aggregating replicates for each (c0, salt) combination...")
    grouped = mapping_df.groupby(["ligand_index", "salt_index", "c0", "salt_conc"], as_index=False).agg(
        cE_mean=("cE", "mean"),
        cE_std=("cE", "std"),
        n_reps=("cE", "count"),
    )

    expected_points = num_ligand * num_salt
    if len(grouped) != expected_points:
        raise ValueError(
            f"Aggregation produced {len(grouped)} points, but expected {expected_points} "
            f"(num_ligand * num_salt). Well-to-condition mapping might be incorrect."
        )

    if (grouped["n_reps"] != replicates).any():
        msg = (
            "WARNING: Some (c0, salt) combinations do not have the expected number of replicates. "
            "Check plate layout and data completeness."
        )
        print(msg)
        analysis_results["warnings"].append(msg)

    # Calculate loading q for each parameter combination
    print("INFO: Calculating loading q for each (c0, salt) combination...")
    # q = (c0 - cE_mean) * v_total / m_resin
    grouped["q"] = (grouped["c0"] - grouped["cE_mean"]) * total_volume / resin_mass

    # Fit Langmuir isotherm for each salt concentration
    print("INFO: Fitting Langmuir isotherms for each salt concentration...")
    fits: List[Dict[str, Any]] = []

    for salt_idx, salt_df in grouped.groupby("salt_index"):
        salt_conc = float(salt_df["salt_conc"].iloc[0])
        cE_vals = salt_df["cE_mean"].to_numpy(dtype=float)
        q_vals = salt_df["q"].to_numpy(dtype=float)

        q_max, K, r2 = fit_langmuir(cE_vals, q_vals)
        fits.append(
            {
                "salt_index": int(salt_idx),
                "salt_conc": salt_conc,
                "q_max": q_max,
                "K": K,
                "r2": r2,
            }
        )

    fits_df = pd.DataFrame(fits)

    # Plot isotherms: all salt concentrations in one plot
    print("INFO: Generating isotherm plot...")
    plt.figure(figsize=(8, 6))

    colors = plt.cm.get_cmap('tab10', num_salt)

    for idx, salt_idx in enumerate(sorted(grouped["salt_index"].unique())):
        salt_df = grouped[grouped["salt_index"] == salt_idx].sort_values("cE_mean")
        salt_conc = float(salt_df["salt_conc"].iloc[0])
        cE_vals = salt_df["cE_mean"].to_numpy(dtype=float)
        q_vals = salt_df["q"].to_numpy(dtype=float)

        color = colors(idx)
        label_base = f"{salt_conc:g} {salt_unit}"

        # Plot data points
        plt.errorbar(
            cE_vals,
            q_vals,
            yerr=salt_df["q"].to_numpy(dtype=float) * 0.0,  # no error bars for q unless desired
            fmt='o',
            color=color,
            label=None,
            alpha=0.8,
        )

        # Overlay fit if available
        fit_row = fits_df[fits_df["salt_index"] == salt_idx]
        if not fit_row.empty and pd.notna(fit_row["q_max"].iloc[0]) and pd.notna(fit_row["K"].iloc[0]):
            q_max = float(fit_row["q_max"].iloc[0])
            K = float(fit_row["K"].iloc[0])
            r2 = fit_row["r2"].iloc[0]
            c_grid = np.linspace(max(0.0, float(np.nanmin(cE_vals))), float(np.nanmax(cE_vals)), 200)
            q_fit = langmuir_isotherm(c_grid, q_max, K)
            label = f"{label_base}, q_max={q_max:.3g}, K={K:.3g}, R2={r2:.3f}" if r2 is not None else (
                f"{label_base}, q_max={q_max:.3g}, K={K:.3g}"
            )
            plt.plot(c_grid, q_fit, '-', color=color, label=label)
        else:
            label = f"{label_base} (fit failed)"
            plt.plot([], [], '-', color=color, label=label)

    plt.xlabel(f"Equilibrium ligand concentration cE [{ligand_unit}]")
    plt.ylabel(f"Loading q [{ligand_unit} * uL / mg]")
    plt.title("Loading isotherms from Tecan plate reader")
    plt.legend()
    plt.tight_layout()

    plot_png_name = f"loading_isotherms_{experiment_id}.png"
    plot_pdf_name = f"loading_isotherms_{experiment_id}.pdf"
    plot_png_path = results_folder_path / plot_png_name
    plot_pdf_path = results_folder_path / plot_pdf_name
    plt.savefig(plot_png_path, dpi=300)
    plt.savefig(plot_pdf_path)
    plt.close()

    analysis_results["plots"]["isotherms_png"] = str(plot_png_path.resolve())
    analysis_results["plots"]["isotherms_pdf"] = str(plot_pdf_path.resolve())

    # Save processed data and fits as CSV
    print("INFO: Saving processed data and fit parameters to CSV...")
    long_csv_path = results_folder_path / f"processed_well_data_{experiment_id}.csv"
    grouped_csv_path = results_folder_path / f"aggregated_isotherm_data_{experiment_id}.csv"
    fits_csv_path = results_folder_path / f"langmuir_fit_parameters_{experiment_id}.csv"

    mapping_df.to_csv(long_csv_path, index=False)
    grouped.to_csv(grouped_csv_path, index=False)
    fits_df.to_csv(fits_csv_path, index=False)

    analysis_results["data_outputs"].update(
        {
            "well_level_data_csv": str(long_csv_path.resolve()),
            "aggregated_data_csv": str(grouped_csv_path.resolve()),
            "langmuir_fit_csv": str(fits_csv_path.resolve()),
        }
    )

    analysis_results["status"] = "success"
    analysis_results["message"] = "Analysis completed successfully."

    # Save the analysis results as JSON
    results_json_file = f"analysis_results_{experiment_id}.json"
    results_json_path = results_folder_path / results_json_file
    with open(results_json_path, 'w') as f:
        json.dump(analysis_results, f, indent=4)
    print(f"Saved analysis results JSON to: {results_json_path}")

    return analysis_results


def main() -> int:
    """Command line interface"""
    parser = argparse.ArgumentParser(description='Analyze Tecan plate reader loading isotherm experiment data.')
    parser.add_argument('experiment_id', nargs='?', help='Experiment ID')
    parser.add_argument('--data-folder', default='../data', help='Data folder path')
    parser.add_argument('--results-folder', default='../results', help='Results folder path')

    args = parser.parse_args()

    try:
        results = analyze_experiment(
            experiment_id=args.experiment_id,
            data_folder=args.data_folder,
            results_folder=args.results_folder,
        )
        if results.get("status") == "success":
            print("SUCCESS: Analysis completed successfully.")
            return 0
        else:
            print(f"ERROR: Analysis finished with status '{results.get('status')}'. Message: {results.get('message')}")
            return 1
    except Exception as e:
        print(f"ERROR: Analysis failed: {e}")
        return 1


if __name__ == "__main__":
    sys.exit(main())
